import { backend, ME, sleep } from './state.ts'
export const currentBoardId = () => 'public'
export const session = () => null
export const setSession = () => {}
export async function tool<T>(name: string, args: any): Promise<T> {
  if (name === 'list_messages') {
    await sleep(150)
    return { subject: args.subject, messages: backend.messages, cursor: null, hasMore: false, nextPollSeconds: 10,
      viewer: { address: ME, roles: [], canPost: !location.search.includes('nopost'), needs: location.search.includes('nopost') ? 'stake' : null, minimum: '10000000000000000000', stake: null, backing: null } } as T
  }
  if (name === 'post_message') {
    await sleep(backend.postDelayMs)
    if (backend.postError) throw new Error("Posting failed")
    backend.posts.push(args)
    const m = { id: backend.messages.length + 1, subject: args.subject, author: ME, badges: [], body: args.body, presentation: args.presentation ?? null, replyTo: args.replyTo ?? null, mentions: [], hidden: null, createdAt: 2 }
    backend.messages.push(m as any)
    return { message: m, notified: 0 } as T
  }
  throw new Error('unexpected tool ' + name)
}

