import { createContext, useContext, useState, type ReactNode } from 'react'
import { ME, sleep } from './state.ts'
type Auth = { address: `0x${string}` | undefined; signedIn: boolean; signIn: () => Promise<void>; signOut: () => void }
const Ctx = createContext<Auth | null>(null)
export function FakeAuthProvider({ children, signedIn: initial = false }: { children: ReactNode; signedIn?: boolean }) {
  const [signedIn, setSignedIn] = useState(initial)
  // Like useSignedIn.signInOnce: the session state is set, then the promise resolves and the mutation calls the tool.
  const signIn = async () => { await sleep(100); setSignedIn(true) }
  return <Ctx value={{ address: ME, signedIn, signIn, signOut: () => setSignedIn(false) }}>{children}</Ctx>
}
export const useAuth = () => useContext(Ctx)!
export const Monogram = ({ label }: { seed: string; label?: string }) => <span>{label ?? 'm'}</span>

